/**
 * Verse Mapping System - Central Index
 *
 * This module provides a centralized interface for verse mappings between translations.
 * Each translation has its own mapping file (e.g., cuvToKjv.ts).
 *
 * To add a new translation:
 * 1. Create a new mapping file (e.g., esvToKjv.ts)
 * 2. Export the mapping and helper functions
 * 3. Import and register it here
 */

import { cuvToKjvMapping, getKjvVerseFromCuv, hasCuvToKjvMapping } from './cuvToKjv';

import { lutToKjvMapping, getKjvVerseFromLut, hasLutToKjvMapping } from './lutToKjv';
import {
  contentSpans,
  reviewedDiscussionSpans,
  sameReference,
  SourceVerseReference,
  VerseReference,
} from './contentSpans';
import { hasBibleSourceReference } from '../../data/bibleSourceReferences';
import { sourceVerseLabelsOverlap } from '../sourceVerseLabels';

export type { VerseReference } from './contentSpans';

export type TranslationCode = 'cuv' | 'kjv' | 'lut' | 'esv' | 'niv' | string;

export interface VerseMappingResult {
  kjvVerse: number;
  hasMapping: boolean;
}

export interface KjvReferenceMapping extends VerseReference {
  hasMapping: boolean;
}

export interface EditionVerseReference extends SourceVerseReference {
  translation: TranslationCode;
}

export interface CanonicalPassage {
  source: EditionVerseReference;
  sourceSpan: SourceVerseReference[];
  kjvSpan: VerseReference[];
  anchor: VerseReference;
  slug: string;
  correspondence: 'reviewed' | 'legacy' | 'unverified';
}

/** Resolve source content before projecting it onto a shared discussion anchor. */
const sourceKjvMembers = (
  fromTranslation: TranslationCode,
  book: string,
  chapter: number,
  verse: number | string,
): { members: VerseReference[]; correspondence: CanonicalPassage['correspondence'] } => {
  const source = { book: book.trim(), chapter: Number(chapter), verse };
  let matching = contentSpans.filter(
    (entry) =>
      entry.translation === fromTranslation &&
      entry.source.some((ref) => sameReference(ref, source)),
  );
  // A point may address a member of a stored combined/part label. Prefer an
  // actual stored point identity; never steal it merely because another label
  // overlaps numerically. Only reviewed source spans can establish this bridge.
  if (
    !matching.length &&
    /^\d+[a-z]?$/i.test(String(verse)) &&
    !hasBibleSourceReference(
      fromTranslation,
      source.book.toLowerCase().replace(/\s+/g, ''),
      source.chapter,
      String(verse),
    )
  ) {
    matching = contentSpans.filter(
      (entry) =>
        entry.translation === fromTranslation &&
        entry.source.some(
          (ref) =>
            sameReference({ ...ref, verse: source.verse }, source) &&
            sourceVerseLabelsOverlap(ref.verse, source.verse),
        ),
    );
  }
  if (matching.length === 1) {
    return { members: matching[0].kjv.map((ref) => ({ ...ref })), correspondence: 'reviewed' };
  }
  if (matching.length > 1) {
    const groups = matching.map((span) => getCanonicalKjvSpan(span.kjv[0]));
    const first = groups[0];
    if (
      groups.some(
        (group) =>
          group.length !== first.length ||
          group.some((ref, index) => !sameReference(ref, first[index])),
      ) ||
      matching.some((span) =>
        span.kjv.some((member) => !first.some((candidate) => sameReference(member, candidate))),
      )
    ) {
      throw new Error('Ambiguous source membership needs a reviewed common KJV discussion span.');
    }
    return { members: first.map((ref) => ({ ...ref })), correspondence: 'reviewed' };
  }

  // Range labels must match a reviewed content span; never truncate them into a post ID.
  if (!/^\d+$/.test(String(verse)) || !Number.isSafeInteger(Number(verse))) {
    throw new Error('This verse needs a reviewed content mapping before linking a KJV discussion.');
  }
  const sourceVerse = Number(verse);

  const mappedVerse =
    fromTranslation === 'cuv'
      ? getKjvVerseFromCuv(book, chapter, sourceVerse)
      : fromTranslation === 'lut'
        ? getKjvVerseFromLut(book, chapter, sourceVerse)
        : null;
  // Preserve the existing tables and fallback outside the reviewed spans.
  // This fallback is compatibility behavior, not a claim of verified content equivalence.
  return {
    members: [{ ...source, verse: mappedVerse ?? sourceVerse }],
    correspondence:
      mappedVerse !== null ? 'legacy' : fromTranslation === 'kjv' ? 'reviewed' : 'unverified',
  };
};

/**
 * A canonical spread applies to KJV itself and every edition projected through it.
 * Conflicting content evidence must be reviewed, never resolved by first match or union.
 */
export const getCanonicalKjvSpan = (reference: VerseReference): VerseReference[] => {
  const discussion = reviewedDiscussionSpans.find((group) =>
    group.kjv.some((member) => sameReference(member, reference)),
  );
  if (discussion) {
    const touching = contentSpans.filter((span) =>
      span.kjv.some((member) =>
        discussion.kjv.some((candidate) => sameReference(member, candidate)),
      ),
    );
    if (
      touching.some((span) =>
        span.kjv.some(
          (member) => !discussion.kjv.some((candidate) => sameReference(member, candidate)),
        ),
      )
    ) {
      throw new Error(
        'The reviewed discussion group does not cover every corresponding content member.',
      );
    }
    return discussion.kjv.map((member) => ({ ...member, book: reference.book }));
  }
  const matching = contentSpans.filter((span) =>
    span.kjv.some((member) => sameReference(member, reference)),
  );
  const first = matching[0]?.kjv;
  if (!first) {
    return [{ ...reference }];
  }
  if (
    matching.some(
      (span) =>
        span.kjv.length !== first.length ||
        span.kjv.some((member, index) => !sameReference(member, first[index])),
    )
  ) {
    throw new Error('Conflicting KJV content spans require review before linking this passage.');
  }
  // Preserve the caller's canonical book spelling used by existing route consumers.
  return first.map((member) => ({ ...member, book: reference.book }));
};

export const resolveCanonicalPassage = (source: EditionVerseReference): CanonicalPassage => {
  const mapped = sourceKjvMembers(source.translation, source.book, source.chapter, source.verse);
  const kjvSpan = getCanonicalKjvSpan(mapped.members[0]);
  if (!mapped.members.every((member) => kjvSpan.some((ref) => sameReference(ref, member)))) {
    throw new Error('Incomplete KJV content span requires review before linking this passage.');
  }
  const anchor = kjvSpan[0];
  return {
    source: { ...source },
    sourceSpan: getTranslationReferencesFromKjv(source.translation, anchor),
    kjvSpan,
    anchor,
    slug: `${anchor.book}-${anchor.chapter}-${anchor.verse}`,
    correspondence: mapped.correspondence,
  };
};

/** Compatibility projection; callers needing study content must retain the full KJV span. */
export const getKjvReferenceFromTranslation = (
  fromTranslation: TranslationCode,
  book: string,
  chapter: number,
  verse: number | string,
): KjvReferenceMapping => {
  const mapped = sourceKjvMembers(fromTranslation, book, chapter, verse);
  const span = getCanonicalKjvSpan(mapped.members[0]);
  return {
    ...span[0],
    hasMapping:
      (mapped.correspondence !== 'unverified' && fromTranslation !== 'kjv') || span.length > 1,
  };
};

/**
 * Resolve a WordPress reference back to the source content for study links.
 * A link to any KJV member of a reviewed span returns the entire source span.
 */
export const getTranslationReferencesFromKjv = (
  translation: TranslationCode,
  reference: VerseReference,
): SourceVerseReference[] => {
  const references = getCanonicalKjvSpan(reference);
  const result: SourceVerseReference[] = [];
  for (const member of references) {
    for (const source of translationReferencesForMember(translation, member)) {
      if (!result.some((existing) => sameReference(existing, source))) {
        result.push(source);
      }
    }
  }
  return result;
};

const translationReferencesForMember = (
  translation: TranslationCode,
  reference: VerseReference,
): SourceVerseReference[] => {
  const span = contentSpans.find(
    (entry) =>
      entry.translation === translation && entry.kjv.some((ref) => sameReference(ref, reference)),
  );
  if (span) {
    return span.source.map((ref) => ({ ...ref }));
  }
  const mappings =
    translation === 'cuv' ? cuvToKjvMapping : translation === 'lut' ? lutToKjvMapping : null;
  const normalizedBook = reference.book.toLowerCase().trim().replace(/\s+/g, '');
  const chapter = mappings?.[normalizedBook]?.[String(reference.chapter)];
  if (!chapter) {
    const book = reference.book.toLowerCase().trim().replace(/\s+/g, '');
    if (!hasBibleSourceReference(translation, book, reference.chapter, String(reference.verse))) {
      return [];
    }
    // A stored range/part can claim this numeric point for different content.
    // Never reverse a KJV reference into that range merely by its label.
    const members = sourceKjvMembers(
      translation,
      reference.book,
      reference.chapter,
      reference.verse,
    ).members;
    return members.some((member) => sameReference(member, reference)) ? [{ ...reference }] : [];
  }
  // Compare content membership, not the first shared anchor, when reversing an individual member.
  return Object.keys(chapter)
    .map((verse) => ({ ...reference, verse: Number(verse) }))
    .filter((source) =>
      sourceKjvMembers(translation, source.book, source.chapter, source.verse).members.some(
        (member) => sameReference(member, reference),
      ),
    );
};

/**
 * Get KJV verse number from any translation's verse number
 *
 * Compatibility projection for callers that need only the verse number.
 * Use getKjvReferenceFromTranslation for routing: content can cross chapters.
 *
 * @param fromTranslation - Source translation code ('cuv', 'lut', or 'kjv')
 * @param book - Bible book name
 * @param chapter - Chapter number
 * @param verse - Verse number in source translation
 * @returns KJV verse number, or original verse if no mapping exists or translation is 'kjv'
 */
export const getKjvVerseFromTranslation = (
  fromTranslation: TranslationCode,
  book: string,
  chapter: number,
  verse: number,
): VerseMappingResult => {
  const result = getKjvReferenceFromTranslation(fromTranslation, book, chapter, verse);
  return { kjvVerse: result.verse, hasMapping: result.hasMapping };
};

/**
 * Check if a translation has verse mappings to KJV
 */
export const hasTranslationMapping = (
  translation: TranslationCode,
  book: string,
  chapter: number,
): boolean => {
  if (
    contentSpans.some(
      (span) =>
        (span.translation === translation &&
          span.source.some((ref) => sameReference(ref, { book, chapter, verse: ref.verse }))) ||
        (translation === 'kjv' &&
          span.kjv.length > 1 &&
          span.kjv.some((ref) => sameReference(ref, { book, chapter, verse: ref.verse }))),
    )
  ) {
    return true;
  }
  if (translation === 'kjv') {
    return false;
  }

  if (translation === 'cuv') {
    return hasCuvToKjvMapping(book, chapter);
  }

  if (translation === 'lut') {
    return hasLutToKjvMapping(book, chapter);
  }

  // Add checks for other translations as they're added
  return false;
};

/**
 * Generate a verse slug using KJV numbering (for WordPress post alignment)
 * This ensures comments can be found regardless of which translation was used
 *
 * Content spans can change the chapter as well as the verse. Source data stays intact.
 *
 * @param book - Bible book name
 * @param chapter - Chapter number
 * @param verse - Verse number (in source translation)
 * @param translation - Source translation code ('cuv', 'lut', or 'kjv')
 * @returns Slug string like "psalms-23-1" (always uses KJV numbering for WordPress posts)
 */
export const generateKjvVerseSlug = (
  book: string,
  chapter: number,
  verse: number | string,
  translation: TranslationCode = 'kjv',
): string => {
  const reference = getKjvReferenceFromTranslation(translation, book, chapter, verse);
  return `${reference.book}-${reference.chapter}-${reference.verse}`;
};

/** A missing correspondence must not crash the reader or invent a WordPress post. */
export const availableKjvVerseSlug = (
  book: string,
  chapter: number,
  verse: number | string,
  translation: TranslationCode = 'kjv',
): string => {
  try {
    return generateKjvVerseSlug(book, chapter, verse, translation);
  } catch {
    return '';
  }
};
