import React, { createContext, useCallback, useContext, useEffect, useState } from 'react';
import { getAuth } from 'firebase/auth';
import { HighlightRequestError, requestAccountHighlights } from '../services/wordpress';
import {
  DEFAULT_HIGHLIGHTS,
  HighlightChange,
  HighlightDocument,
  parseHighlightDocument,
} from '../utils/highlights';

type HighlightContextValue = {
  ownerUid: string | null;
  document: HighlightDocument;
  ready: boolean;
  hasSnapshot: boolean;
  loading: boolean;
  saving: boolean;
  error: string | null;
  refresh: () => Promise<void>;
  change: (change: HighlightChange, expectedRevision?: number) => Promise<boolean>;
  clearLocalCache: () => void;
};
const HighlightContext = createContext<HighlightContextValue | null>(null);
export const highlightCacheKey = (uid: string) => `revelationary.highlights.v1:${uid}`;

type HighlightOperation = { revision: number; operationId: string; change: HighlightChange };
// A new scope is also a new generation, including A -> B -> A account switches.
// Async work keeps its original scope and can never update a later generation.
type AccountScope = {
  uid: string | null;
  alive: boolean;
  busy: boolean;
  controller: AbortController | null;
  retry: HighlightOperation | null;
  snapshot: HighlightDocument | null;
};
type AccountState = {
  scope: AccountScope;
  snapshot: HighlightDocument | null;
  ready: boolean;
  loading: boolean;
  saving: boolean;
  error: string | null;
};
function initialAccountState(uid: string | null): AccountState {
  let snapshot: HighlightDocument | null = null;
  try {
    const raw = uid && localStorage.getItem(highlightCacheKey(uid));
    if (raw) {
      snapshot = parseHighlightDocument(JSON.parse(raw));
    }
  } catch {
    /* A missing or invalid cache must not prevent signing in. */
  }
  return {
    scope: { uid, alive: false, busy: false, controller: null, retry: null, snapshot },
    snapshot,
    ready: false,
    loading: false,
    saving: false,
    error: null,
  };
}

export function HighlightProvider({
  uid,
  wpToken,
  children,
}: {
  uid: string | null;
  wpToken: string | null;
  children: React.ReactNode;
}) {
  const [state, setState] = useState(() => initialAccountState(uid));
  // Reset this provider's data before rendering children, without remounting them.
  // React discards this render and immediately renders the new account state.
  if (state.scope.uid !== uid) {
    setState(initialAccountState(uid));
  }
  const { scope, snapshot, ready, loading, saving, error } = state;
  const cacheKey = scope.uid ? highlightCacheKey(scope.uid) : null;
  const update = useCallback(
    (patch: Partial<Omit<AccountState, 'scope'>>) => {
      setState((previous) => (previous.scope === scope ? { ...previous, ...patch } : previous));
    },
    [scope],
  );
  const current = useCallback(
    () => scope.alive && !!scope.uid && getAuth().currentUser?.uid === scope.uid,
    [scope],
  );
  const install = useCallback(
    (value: HighlightDocument) => {
      scope.snapshot = value;
      update({ snapshot: value });
      try {
        if (cacheKey) {
          localStorage.setItem(cacheKey, JSON.stringify(value));
        }
      } catch {
        /* Server persistence is authoritative even if local storage is full. */
      }
    },
    [scope, cacheKey, update],
  );
  const refresh = useCallback(async () => {
    if (!current() || !wpToken || scope.busy) {
      return;
    }
    scope.controller?.abort();
    const request = new AbortController();
    scope.controller = request;
    update({ loading: true });
    try {
      const value = await requestAccountHighlights(undefined, request.signal);
      if (!request.signal.aborted && current()) {
        install(value);
        update({ ready: true, error: null });
      }
    } catch (failure) {
      if (!request.signal.aborted && current()) {
        update({
          error: failure instanceof Error ? failure.message : 'Highlights could not be loaded.',
        });
      }
    } finally {
      if (!request.signal.aborted && current()) {
        update({ loading: false });
      }
    }
  }, [scope, wpToken, current, install, update]);
  useEffect(() => {
    scope.alive = true;
    update({ loading: false, saving: false });
    void refresh();
    const onFocus = () => {
      if (window.document.visibilityState === 'visible') {
        void refresh();
      }
    };
    const onStorage = (event: StorageEvent) => {
      if (event.key === cacheKey) {
        void refresh();
      }
    };
    window.addEventListener('focus', onFocus);
    window.addEventListener('online', onFocus);
    window.addEventListener('storage', onStorage);
    window.document.addEventListener('visibilitychange', onFocus);
    return () => {
      scope.alive = false;
      scope.controller?.abort();
      scope.busy = false;
      window.removeEventListener('focus', onFocus);
      window.removeEventListener('online', onFocus);
      window.removeEventListener('storage', onStorage);
      window.document.removeEventListener('visibilitychange', onFocus);
    };
  }, [refresh, cacheKey, scope, update]);
  const change = async (intent: HighlightChange, expectedRevision?: number): Promise<boolean> => {
    if (!current() || !wpToken || !ready || !scope.snapshot || scope.busy) {
      return false;
    }
    scope.busy = true;
    update({ saving: true, error: null });
    scope.controller?.abort();
    update({ loading: false });
    const request = new AbortController();
    scope.controller = request;
    const previous = scope.retry;
    const operation =
      previous && JSON.stringify(previous.change) === JSON.stringify(intent)
        ? previous
        : {
            revision: expectedRevision ?? scope.snapshot.revision,
            operationId: crypto.randomUUID(),
            change: intent,
          };
    scope.retry = operation;
    try {
      const result = await requestAccountHighlights(operation, request.signal);
      if (!current() || request.signal.aborted) {
        return false;
      }
      install(result);
      scope.retry = null;
      return true;
    } catch (failure) {
      if (!current() || request.signal.aborted) {
        return false;
      }
      if (failure instanceof HighlightRequestError && failure.status === 409) {
        scope.retry = null;
        try {
          const latest = await requestAccountHighlights(undefined, request.signal);
          if (current() && !request.signal.aborted) {
            install(latest);
          }
        } catch {
          if (current() && !request.signal.aborted) {
            update({
              ready: false,
              error:
                'Highlights changed elsewhere, but the latest version could not be loaded. Reload before retrying.',
            });
          }
          return false;
        }
      }
      if (current() && !request.signal.aborted) {
        update({
          error:
            failure instanceof Error
              ? failure.message
              : 'Your highlight was not saved. Please retry.',
        });
      }
      return false;
    } finally {
      if (scope.controller === request) {
        scope.busy = false;
        if (current()) {
          update({ saving: false });
        }
      }
    }
  };
  const clearLocalCache = () => {
    if (!current()) {
      return;
    }
    scope.controller?.abort();
    scope.retry = null;
    try {
      if (cacheKey) {
        localStorage.removeItem(cacheKey);
      }
    } catch {
      /* No local cache available. */
    }
    scope.snapshot = null;
    scope.busy = false;
    update({ snapshot: null, ready: false, loading: false, saving: false, error: null });
  };
  return (
    <HighlightContext.Provider
      value={{
        ownerUid: scope.uid,
        document: snapshot || DEFAULT_HIGHLIGHTS,
        ready,
        hasSnapshot: !!snapshot,
        loading,
        saving,
        error,
        refresh,
        change,
        clearLocalCache,
      }}
    >
      {children}
    </HighlightContext.Provider>
  );
}
export function useAccountHighlights() {
  const context = useContext(HighlightContext);
  if (!context) {
    throw new Error('Highlights require HighlightProvider.');
  }
  return context;
}
