// Helper function to get video sources based on translation
const getVideoSources = (translation: string | any = 'kjv'): VideoSources => {
  if (translation === 'cuv') {
    return videoSourcesCUV;
  }
  if (translation === 'lut') {
    return videoSourcesLUT;
  }
  if (translation === 'es-rv09') {
    return videoSourcesES;
  }
  if (translation === 'it-db1885') {
    return videoSourcesIT;
  }
  if (translation === 'cs-bkr') {
    return videoSourcesCS;
  }
  if (translation === 'sv-skb') {
    return videoSourcesSV;
  }
  if (translation === 'id-tsi') {
    return videoSourcesID;
  }
  if (translation === 'nl-nld1939') {
    return videoSourcesNL;
  }
  if (translation === 'vi-ovcb') {
    return videoSourcesVI;
  }
  return videoSourcesKJV; // Default to KJV
};

// Define the props expected for the VideoModal component
interface VideoModalProps {
  currentBook?: string;
  currentChapter?: number;
  translation?: string; // Add translation prop
}

// eslint-ignore-next-line
const VideoModal = ({
  currentBook = '',
  currentChapter = 1,
  translation = 'kjv', // Default to KJV
}: VideoModalProps) => {
  const [open, setOpen] = useState(false);
  const { t } = useTranslation();

  const handleOpen = () => setOpen(true);
  const handleClose = () => setOpen(false);

  const generateVideoUrl = (book: string, chapter: number, trans: string | any = 'kjv') => {
    if (!book || !chapter) {
      return '';
    }

    // Get the appropriate video sources for the translation
    const videoSources = getVideoSources(trans);

    // Trim spaces and make sure the format is correct
    const cleanBook = book.trim().replace(/\s+/g, '-').toLowerCase();

    if (videoSources[cleanBook]) {
      const chapterRanges = Object.keys(videoSources[cleanBook]).map(Number);

      // Iterate over each chapter range
      for (let i = 0; i < chapterRanges.length; i++) {
        const startChapter = chapterRanges[i];
        const nextStartChapter = chapterRanges[i + 1]; // Next range's start chapter
        const endChapter = nextStartChapter ? nextStartChapter - 1 : Infinity; // If there's no next range, the end is infinite

        // Check if the current chapter falls within the range (startChapter to endChapter)
        if (chapter >= startChapter && chapter <= endChapter) {
          return videoSources[cleanBook][startChapter];
        }
      }
    }

    // Return a default or fallback video URL if not found
    return '';
  };

  const videoUrl = generateVideoUrl(currentBook, currentChapter, translation);

  // Generate and inject VideoObject schema when modal is open and video is available
  useEffect(() => {
    if (open && videoUrl && currentBook && currentChapter) {
      const videoId = extractYouTubeId(videoUrl);
      if (videoId) {
        const bookName = formatBookName(currentBook);
        const videoSchema = {
          '@context': 'https://schema.org',
          '@type': 'VideoObject',
          name: `${bookName} Chapter ${currentChapter} - Bible Project Video`,
          description: `Bible Project overview video for ${bookName} Chapter ${currentChapter}. Study the Bible online with interactive tools and visual explanations.`,
          thumbnailUrl: `https://img.youtube.com/vi/${videoId}/maxresdefault.jpg`,
          uploadDate: '2024-01-01', // Bible Project videos are from various dates
          duration: 'PT5M30S', // Approximate duration, update if exact duration is known
          contentUrl: `https://www.youtube.com/watch?v=${videoId}`,
          embedUrl: `https://www.youtube-nocookie.com/embed/${videoId}`,
          publisher: {
            '@type': 'Organization',
            name: 'The Bible Project',
            url: 'https://www.bibleproject.com/',
            logo: {
              '@type': 'ImageObject',
              url: 'https://revelationary.online/static/media/BP_mono-wht.png',
            },
          },
          about: {
            '@type': 'CreativeWork',
            name: `${bookName} Chapter ${currentChapter}`,
            description: `Bible study content for ${bookName} Chapter ${currentChapter}`,
          },
        };

        // Remove any existing VideoObject schema
        const existingScripts = document.querySelectorAll('script[data-video-schema]');
        existingScripts.forEach((script) => script.remove());

        // Add new VideoObject schema
        const script = document.createElement('script');
        script.type = 'application/ld+json';
        script.setAttribute('data-video-schema', 'true');
        script.textContent = JSON.stringify(videoSchema, null, 2);
        document.head.appendChild(script);

        // Cleanup function
        return () => {
          const scripts = document.querySelectorAll('script[data-video-schema]');
          scripts.forEach((script) => script.remove());
        };
      }
    }
  }, [open, videoUrl, currentBook, currentChapter]);

  return (
    <div>
      <Tooltip
        title={
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: '8px',
              paddingRight: '10px',
            }}
          >
            <img
              src={TBPLogoSQ}
              style={{ width: '75px', height: '75px' }}
              alt={interfaceText('The Bible Project Logo')}
              width="75"
              height="75"
            />
            <span>{String(t('guide.watchVideoSummary'))}</span>
          </div>
        }
      >
        <Box sx={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
          <IconButton
            onClick={handleOpen}
            sx={{
              mt: '-5px',
              width: '50px',
              height: '50px',
              ml: 3,
              borderRadius: '50%',
            }}
          >
            {/* <OndemandVideo /> */}
            <SlowMotionVideo />
          </IconButton>
          <Typography
            variant="body2"
            sx={{
              color: '#888',
              fontSize: '12px',
              width: '100%',
              textAlign: 'center',
              display: { xs: 'none', md: 'block' },
            }}
          >
            {String(t('guide.watchVideoSummary'))}
          </Typography>
        </Box>
      </Tooltip>

      <Modal open={open} onClose={handleClose}>
        <Box
          sx={(theme) => ({
            ...getModalSurface(theme.palette.mode),
            position: 'absolute',
            top: '50%',
            left: '50%',
            transform: 'translate(-50%, -50%)',
            outline: 'none',
            width: {
              xs: '90%',
              sm: '80%',
              md: '60%',
            },
            maxWidth: {
              xs: '100vw',
              sm: '100vw',
              md: '1000px',
            },
            maxHeight: {
              xs: '80vh',
              sm: '80vh',
              md: '50vh',
            },
            '& iframe': {
              width: '100%',
              height: '100%',
              maxWidth: '100%',
              maxHeight: '100%',
              aspectRatio: '16/9',
            },
          })}
        >
          <a href="https://www.bibleproject.com/" target="_blank" rel="noopener noreferrer">
            <img
              src={TBPLogo}
              height="36"
              style={{
                marginLeft: 3,
                backgroundColor: '#212121',
                boxShadow: '0px 0px 10px 0px rgba(0, 0, 0, 0.5)',
              }}
              alt={interfaceText('The Bible Project Logo')}
            />
          </a>
          <Box>
            {videoUrl ? (
              <iframe
                src={videoUrl}
                title={interfaceText('The Bible Project Video')}
                frameBorder="0"
                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
                referrerPolicy="strict-origin-when-cross-origin"
                allowFullScreen
                style={{
                  filter: 'grayscale(1) contrast(2.5)',
                  opacity: 0.8,
                }}
              ></iframe>
            ) : (
              <p>{interfaceText('No video available for this chapter.')}</p>
            )}
          </Box>
        </Box>
      </Modal>
    </div>
  );
};

export default VideoModal;
