/**
 * Draggable and droppable pill tile for Hebrew letters/combinations
 */

import React from 'react';
import { useDraggable, useDroppable } from '@dnd-kit/core';
import { Box, Typography, Tooltip } from '@mui/material';

export interface HebrewTileData {
  id: string;
  letters: string[];
  meaning: string;
  wordIndex?: number; // Which word this tile belongs to (for visual grouping)
  /** When set, show this Hebrew instead of letters.join() - e.g. original word when combined letters match */
  displayHebrew?: string;
}

interface HebrewLetterTileProps {
  tile: HebrewTileData;
  userLanguage: string;
  isOver?: boolean;
  isHighlighted?: boolean;
  hebrewFont?: string;
  /** Called when user clicks a combined tile (letters.length > 1) to split it back into individual letters */
  onDestructure?: (tileId: string) => void;
  /** Tooltip text when hovering over a combined tile (for click-to-split) */
  destructureTooltip?: string;
}

const HebrewLetterTile: React.FC<HebrewLetterTileProps> = ({
  tile,
  isOver = false,
  isHighlighted = false,
  hebrewFont,
  onDestructure,
  destructureTooltip = 'Click to split into individual letters',
}) => {
  const {
    attributes,
    listeners,
    setNodeRef: setDraggableRef,
    transform,
    isDragging,
  } = useDraggable({
    id: tile.id,
    data: { tile },
  });

  const { setNodeRef: setDroppableRef, isOver: isOverThis } = useDroppable({
    id: tile.id,
    data: { tile },
  });

  const setRefs = (node: HTMLDivElement | null) => {
    setDraggableRef(node);
    setDroppableRef(node);
  };

  const hebrewDisplay = tile.displayHebrew ?? tile.letters.join('');
  const canDestructure = tile.letters.length > 1 && onDestructure;

  const style: React.CSSProperties = {
    transform: transform ? `translate3d(${transform.x}px, ${transform.y}px, 0)` : undefined,
    opacity: isDragging ? 0.5 : 1,
    cursor: isDragging ? 'grabbing' : canDestructure ? 'pointer' : 'grab',
  };

  const handleClick = (e: React.MouseEvent) => {
    if (canDestructure) {
      e.stopPropagation();
      onDestructure(tile.id);
    }
  };

  const tileContent = (
    <Box
      ref={setRefs}
      {...listeners}
      {...attributes}
      onClick={handleClick}
      sx={{
        display: 'inline-flex',
        touchAction: 'none',
        userSelect: 'none',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        minWidth: 48,
        minHeight: 64,
        px: 1.5,
        py: 1,
        mx: 0.5,
        my: 0.5,
        borderRadius: 2,
        backgroundColor: (theme) =>
          isHighlighted
            ? theme.palette.mode === 'dark'
              ? 'rgba(25, 118, 210, 0.35)'
              : 'rgba(25, 118, 210, 0.18)'
            : isOverThis || isOver
              ? theme.palette.mode === 'dark'
                ? 'rgba(255, 255, 255, 0.2)'
                : 'rgba(0, 0, 0, 0.08)'
              : theme.palette.mode === 'dark'
                ? 'rgba(255, 255, 255, 0.08)'
                : 'rgba(0, 0, 0, 0.04)',
        border: (theme) =>
          `2px solid ${
            isHighlighted
              ? theme.palette.primary.main
              : isOverThis || isOver
                ? theme.palette.primary.main
                : theme.palette.mode === 'dark'
                  ? 'rgba(255, 255, 255, 0.2)'
                  : 'rgba(0, 0, 0, 0.1)'
          }`,
        transition: 'background-color 0.2s, border-color 0.2s',
        '&:hover': {
          backgroundColor: (theme) =>
            theme.palette.mode === 'dark' ? 'rgba(255, 255, 255, 0.12)' : 'rgba(0, 0, 0, 0.06)',
        },
      }}
      style={style}
    >
      <Typography
        variant="h6"
        sx={{
          fontFamily: hebrewFont || 'serif',
          direction: 'rtl',
          fontSize: '1.5rem',
          lineHeight: 1.2,
        }}
      >
        {hebrewDisplay}
      </Typography>
      <Typography
        variant="caption"
        sx={{
          mt: 0.5,
          fontSize: '0.7rem',
          textAlign: 'center',
          maxWidth: 260,
          color: 'text.secondary',
          whiteSpace: 'normal',
          wordBreak: 'break-word',
          lineHeight: 1.3,
        }}
      >
        {tile.meaning}
      </Typography>
    </Box>
  );

  return canDestructure ? (
    <Tooltip title={destructureTooltip} placement="top">
      {tileContent}
    </Tooltip>
  ) : (
    tileContent
  );
};

export default HebrewLetterTile;
