import React, { forwardRef, useEffect, useImperativeHandle, useRef, useState } from 'react';
import {
  Box,
  Button,
  CircularProgress,
  Dialog,
  IconButton,
  InputBase,
  Popover,
  Tooltip,
  Typography,
} from '@mui/material';
import BorderColorIcon from '@mui/icons-material/BorderColor';
import CheckIcon from '@mui/icons-material/Check';
import AddIcon from '@mui/icons-material/Add';
import CircleOutlinedIcon from '@mui/icons-material/CircleOutlined';
import useHighlight from '../../hooks/useHighlight';
import { useTranslation } from '../../hooks/useTranslation';
import { HighlightDocument, PaletteRow, mergePaletteDraft } from '../../utils/highlights';
import { getModalSurface } from '../../utils/modalSurface';

type EditorHandle = { close: () => Promise<void> };
const failureMotion = {
  animation: 'highlightWobble 320ms ease-in-out',
  '@keyframes highlightWobble': {
    '0%, 100%': { translate: '0' },
    '25%, 75%': { translate: '-4px' },
    '50%': { translate: '4px' },
  },
  '@media (prefers-reduced-motion: reduce)': { animation: 'none' },
};
function paletteRows(document: HighlightDocument, verseKey?: string): PaletteRow[] {
  const rows = Object.entries(document.palette).map(([color, label]) => ({
    id: color,
    original: color as string | null,
    color,
    label,
  }));
  const current = verseKey && document.entries[verseKey];
  if (current && !(current in document.palette) && rows.length < 64) {
    rows.push({ id: current, original: current, color: current, label: '' });
  }
  return rows;
}
export const HighlightColorEditor = forwardRef<
  EditorHandle,
  { verseKey?: string; onDone?: () => void; onFailure?: (failed: boolean) => void }
>(function HighlightColorEditor({ verseKey, onDone, onFailure }, ref) {
  const { t } = useTranslation();
  const { document, ready, loading, saving, error, change } = useHighlight();
  const [rows, setRows] = useState(() => paletteRows(document, verseKey));
  const rowsRef = useRef(rows);
  const original = useRef(document);
  const expectedRevision = useRef<number | undefined>(document.revision);
  const [selected, setSelected] = useState(
    (verseKey && document.entries[verseKey]) || document.preferred,
  );
  const selectedRef = useRef(selected);
  const dirty = useRef(false);
  const verseDirty = useRef(false);
  const removing = useRef(false);
  const closing = useRef(false);
  const [failed, setFailed] = useState(false);
  const onDoneRef = useRef(onDone);
  onDoneRef.current = onDone;
  const fail = () => {
    closing.current = true;
    setFailed(true);
  };
  useEffect(() => {
    if (!ready && !loading && error) {
      fail();
    }
  }, [ready, loading, error]);
  useEffect(() => {
    onFailure?.(failed);
    if (!failed) {
      return;
    }
    const timer = window.setTimeout(() => onDoneRef.current?.(), 320);
    return () => window.clearTimeout(timer);
  }, [failed, onFailure]);
  useEffect(() => {
    if (dirty.current || closing.current) {
      return;
    }
    const next = paletteRows(document, verseKey);
    rowsRef.current = next;
    setRows(next);
    original.current = document;
    expectedRevision.current = document.revision;
    const choice = (verseKey && document.entries[verseKey]) || document.preferred;
    selectedRef.current = choice;
    setSelected(choice);
  }, [document, verseKey]);
  const updateRows = (next: PaletteRow[]) => {
    rowsRef.current = next;
    setRows(next);
    dirty.current = true;
  };
  const choose = (id: string) => {
    removing.current = false;
    selectedRef.current = id;
    setSelected(id);
    dirty.current = true;
    if (verseKey) {
      verseDirty.current = true;
    }
  };
  const close = async () => {
    if (closing.current || saving) {
      return;
    }
    if (!dirty.current) {
      onDone?.();
      return;
    }
    if (!ready) {
      fail();
      return;
    }
    let palette: Record<string, string>;
    try {
      palette = mergePaletteDraft(original.current, document, rowsRef.current);
    } catch {
      fail();
      return;
    }
    const chosen =
      rowsRef.current.find((row) => row.id === selectedRef.current)?.color || document.preferred;
    const preferred = Object.prototype.hasOwnProperty.call(palette, chosen)
      ? chosen
      : Object.keys(palette)[0];
    closing.current = true;
    const saved = await change(
      {
        kind: 'palette-edit',
        palette,
        preferred,
        ...(verseKey && verseDirty.current
          ? { verse: { key: verseKey, color: removing.current ? null : chosen } }
          : {}),
      },
      expectedRevision.current,
    );
    if (saved) {
      dirty.current = false;
      onDone?.();
    } else {
      fail();
    }
  };
  useImperativeHandle(ref, () => ({ close }));
  const editColor = (id: string, color: string) => {
    updateRows(rowsRef.current.map((row) => (row.id === id ? { ...row, color } : row)));
    choose(id);
  };
  return (
    <Box
      data-highlight-failed={failed || undefined}
      sx={{ p: 0.75, width: 204, maxWidth: 'calc(100vw - 64px)', textAlign: 'left' }}
    >
      {loading && !ready && (
        <Typography role="status" sx={{ p: 1, fontSize: 12 }}>
          {t('common.loading')}
        </Typography>
      )}
      <Box
        role="group"
        aria-label={String(t('highlight.colours'))}
        sx={{ maxHeight: 320, overflowY: 'auto' }}
      >
        {rows.map((row, index) => (
          <Box
            key={row.id}
            sx={{
              display: 'flex',
              alignItems: 'center',
              gap: 0.75,
              minHeight: 38,
              px: 0.75,
              borderRadius: '3px',
              '&:focus-within': { bgcolor: 'action.hover' },
            }}
          >
            <Box
              component="input"
              type="color"
              aria-label={String(t('highlight.colour', { number: index + 1 }))}
              title={row.color.toUpperCase()}
              value={row.color}
              disabled={!ready || saving || failed}
              onChange={(event: React.ChangeEvent<HTMLInputElement>) =>
                editColor(row.id, event.target.value)
              }
              sx={{
                width: 26,
                height: 26,
                flexShrink: 0,
                p: 0,
                border: 0,
                bgcolor: 'transparent',
                cursor: 'pointer',
                '&::-webkit-color-swatch-wrapper': { p: 0 },
                '&::-webkit-color-swatch': { border: '1px solid #888', borderRadius: '3px' },
                '&::-moz-color-swatch': { border: '1px solid #888', borderRadius: '3px' },
                '&:focus-visible': {
                  outline: '2px solid',
                  outlineColor: 'text.primary',
                  outlineOffset: 2,
                },
              }}
            />
            <InputBase
              value={row.label}
              placeholder={row.color.toUpperCase()}
              disabled={!ready || saving || failed}
              inputProps={{
                'aria-label': String(t('highlight.colourLabel', { number: index + 1 })),
                maxLength: 12,
              }}
              onFocus={(event) => event.target.select()}
              onChange={(event) =>
                updateRows(
                  rowsRef.current.map((item) =>
                    item.id === row.id ? { ...item, label: event.target.value.slice(0, 12) } : item,
                  ),
                )
              }
              sx={{
                flex: 1,
                minWidth: 0,
                fontSize: 13,
                '& input': { py: 0.75 },
                '& input::placeholder': { color: 'text.secondary', opacity: 1 },
              }}
            />
            <IconButton
              size="small"
              disableRipple
              disabled={!ready || saving || failed}
              aria-label={String(
                t(verseKey ? 'highlight.applyColour' : 'highlight.useColour', {
                  label: row.label || row.color.toUpperCase(),
                }),
              )}
              aria-pressed={selected === row.id}
              onClick={() => {
                choose(row.id);
                if (verseKey) {
                  void close();
                }
              }}
              sx={{
                width: 30,
                height: 30,
                color: selected === row.id ? 'text.primary' : 'text.disabled',
                '&:hover': { bgcolor: 'transparent' },
              }}
            >
              {selected === row.id ? (
                <CheckIcon sx={{ fontSize: 17 }} />
              ) : (
                <CircleOutlinedIcon sx={{ fontSize: 14 }} />
              )}
            </IconButton>
          </Box>
        ))}
      </Box>
      <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', px: 0.5 }}>
        <Tooltip title={t('highlight.addColour')}>
          <span>
            <IconButton
              size="small"
              disableRipple
              aria-label={String(t('highlight.addColour'))}
              disabled={!ready || saving || failed || rows.length >= 64}
              onClick={() => {
                let value = 0x808080;
                while (
                  rowsRef.current.some(
                    (row) => row.color === `#${value.toString(16).padStart(6, '0')}`,
                  )
                ) {
                  value++;
                }
                const color = `#${value.toString(16).padStart(6, '0')}`;
                const id = `new-${rowsRef.current.length}`;
                updateRows([...rowsRef.current, { id, original: null, color, label: '' }]);
              }}
            >
              <AddIcon sx={{ fontSize: 18 }} />
            </IconButton>
          </span>
        </Tooltip>
        {saving && (
          <CircularProgress
            aria-label={String(t('highlight.savingColours'))}
            size={14}
            color="inherit"
          />
        )}
        {verseKey && document.entries[verseKey] && (
          <Button
            size="small"
            disabled={!ready || saving || failed}
            sx={{ fontSize: 12, textTransform: 'none', color: 'text.secondary' }}
            onClick={() => {
              removing.current = true;
              verseDirty.current = true;
              dirty.current = true;
              void close();
            }}
          >
            {t('highlight.removeHighlight')}
          </Button>
        )}
      </Box>
      {!ready && !loading && !error && (
        <Typography sx={{ p: 1, fontSize: 12 }}>{t('highlight.signInToSave')}</Typography>
      )}
    </Box>
  );
});

export function VerseHighlightDialog({
  verseKey,
  onClose,
}: {
  verseKey: string | null;
  onClose: () => void;
}) {
  const { ownerUid } = useHighlight();
  const { t } = useTranslation();
  const editor = useRef<EditorHandle>(null);
  const [failed, setFailed] = useState(false);
  return (
    <Dialog
      open={!!verseKey}
      onClose={() => void editor.current?.close()}
      aria-label={String(t('highlight.verseHighlight'))}
      maxWidth="xs"
      PaperProps={{
        sx: (theme) => ({
          ...getModalSurface(theme.palette.mode),
          ...(failed ? failureMotion : {}),
        }),
      }}
    >
      {verseKey && (
        <HighlightColorEditor
          ref={editor}
          key={`${ownerUid || 'signed-out'}:${verseKey}`}
          verseKey={verseKey}
          onDone={onClose}
          onFailure={setFailed}
        />
      )}
    </Dialog>
  );
}
export default function HighlightColorSelect({ loggedIn }: { loggedIn: boolean }) {
  const { t } = useTranslation();
  const [anchorEl, setAnchorEl] = useState<HTMLElement | null>(null);
  const editor = useRef<EditorHandle>(null);
  const [failed, setFailed] = useState(false);
  const { document, error, ownerUid } = useHighlight();
  return (
    <>
      <Tooltip title={t(loggedIn ? 'highlight.coloursAndLabels' : 'highlight.signInToSave')}>
        <IconButton
          disableRipple
          aria-label={String(t('highlight.coloursAndLabels'))}
          aria-haspopup="dialog"
          aria-expanded={!!anchorEl}
          onClick={(event) => {
            setFailed(false);
            setAnchorEl(event.currentTarget);
          }}
          sx={{ '&:hover': { bgcolor: 'transparent' } }}
        >
          <BorderColorIcon
            sx={{
              width: 22,
              height: 22,
              borderBottom: '3px solid',
              borderColor: error ? 'warning.main' : document.preferred,
            }}
          />
        </IconButton>
      </Tooltip>
      <Popover
        anchorEl={anchorEl}
        open={!!anchorEl}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'left' }}
        transformOrigin={{ vertical: 'top', horizontal: 'left' }}
        onClose={() => void editor.current?.close()}
        PaperProps={{
          sx: (theme) => ({
            ...getModalSurface(theme.palette.mode),
            mt: '6px',
            ...(failed ? failureMotion : {}),
          }),
        }}
      >
        <Box role="dialog" aria-label={String(t('highlight.coloursAndLabels'))}>
          {anchorEl && (
            <HighlightColorEditor
              key={ownerUid || 'signed-out'}
              ref={editor}
              onDone={() => setAnchorEl(null)}
              onFailure={setFailed}
            />
          )}
        </Box>
      </Popover>
    </>
  );
}
