import type { CSSProperties } from 'react';
import Box from '@mui/material/Box';

import flourishImage from '../../assets/flourish3-gordon-johnson.png';

interface VerseDropCapProps {
  readonly text: string;
  readonly isDarkMode: boolean;
  readonly isSelected: boolean;
  readonly selectedClassName: string;
  readonly selectedStyle?: CSSProperties;
}

/**
 * Chapter-opening drop cap — grid layout avoids float overlap across translations.
 */
export function VerseDropCap({
  text,
  isDarkMode,
  isSelected,
  selectedClassName,
  selectedStyle,
}: VerseDropCapProps): JSX.Element {
  const firstLetter = text.charAt(0);
  const firstSpaceIndex = text.indexOf(' ');
  const restOfFirstWord = firstSpaceIndex > 0 ? text.slice(1, firstSpaceIndex) : text.slice(1);
  const restOfVerse = firstSpaceIndex > 0 ? text.slice(firstSpaceIndex) : '';

  return (
    <Box component="span" className="verse-dropcap">
      <Box component="span" className="verse-dropcap__letter-wrap" aria-hidden="true">
        <Box
          component="span"
          className="verse-dropcap__letter"
          sx={{
            display: 'inline-block',
            position: 'relative',
            fontSize: { xs: '4rem', sm: '5rem', md: '6rem' },
            lineHeight: { xs: 0.8, sm: 0.75, md: 0.7 },
            fontWeight: 700,
            fontFamily: 'serif',
            color: 'text.primary',
            verticalAlign: 'top',
            paddingLeft: { xs: '45px', sm: '60px', md: '75px' },
            paddingRight: 0,
            paddingTop: { xs: '0.05em', sm: '0.08em', md: '0.1em' },
            paddingBottom: 0,
            zIndex: 1,
          }}
        >
          <Box
            component="img"
            src={flourishImage}
            alt=""
            className="verse-dropcap__flourish"
            sx={{
              position: 'absolute',
              transform: 'rotate(12deg)',
              top: { xs: '-10px', sm: '-15px', md: '-20px' },
              left: { xs: '5px', sm: '5px', md: '5px' },
              width: { xs: '90px', sm: '120px', md: '150px' },
              height: 'auto',
              opacity: (theme) => (theme.palette.mode === 'light' ? 0.25 : 0.35),
              zIndex: 0,
              pointerEvents: 'none',
              mixBlendMode: 'multiply',
              filter: isDarkMode ? 'invert(1)' : 'none',
            }}
          />
          {firstLetter}
        </Box>
      </Box>
      <Box
        component="span"
        className={`verse-dropcap__text ${isSelected ? selectedClassName : 'verse__text-inner'}`}
        style={isSelected ? selectedStyle : undefined}
      >
        {restOfFirstWord}
        {restOfVerse}
      </Box>
    </Box>
  );
}
