import { AuthApiError } from '../services/authApi';

export const mapAuthApiErrorMessage = (error: unknown, fallback: string): string => {
  if (!(error instanceof AuthApiError)) {
    switch ((error as { code?: string })?.code) {
      case 'auth/invalid-credential':
      case 'auth/wrong-password':
      case 'auth/user-not-found':
        return "We couldn't verify that email and password. If you already started signing up, use the same password to finish setup.";
      case 'auth/email-already-in-use':
        return 'An account already exists for this email. Please sign in with its password.';
      case 'auth/weak-password':
        return 'Please choose a stronger password with at least 6 characters.';
      case 'auth/too-many-requests':
        return 'Too many attempts. Please wait and try again.';
      case 'auth/network-request-failed':
        return "Couldn't connect. Check your connection and try again.";
    }
    return error instanceof Error ? error.message : fallback;
  }

  switch (error.code) {
    case 'captcha_failed':
      return 'Captcha verification failed. Please try again.';
    case 'user_exists':
      return 'An account already exists for this email.';
    case 'invalid_email':
    case 'invalid_name':
    case 'invalid_username':
      return error.message;
    case 'rate_limited':
      return 'Too many attempts. Please wait and try again.';
    case 'invalid_token':
    case 'missing_token':
    case 'session_changed':
      return 'Your session expired. Please sign in again.';
    default:
      return error.message || fallback;
  }
};
