import { interfaceText } from '../../i18n/interfaceText';
/**
 * IQ Bible Sections Component
 * Displays verse information from IQ Bible API in organized sections
 * Fetches data on-demand when sections are expanded
 */

import React from 'react';
import Box from '@mui/material/Box';
import Typography from '@mui/material/Typography';
import CircularProgress from '@mui/material/CircularProgress';
import Button from '@mui/material/Button';
import { hebrewResourceMessage } from '../../i18n/catalogs';
import Accordion from '@mui/material/Accordion';
import AccordionSummary from '@mui/material/AccordionSummary';
import AccordionDetails from '@mui/material/AccordionDetails';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import { OriginalTextResponse } from '../../services/iqBibleService';

interface IqBibleSectionsProps {
  data: {
    originalText?: OriginalTextResponse | null;
  };
  loading: {
    originalText: boolean;
  };
  error?: string;
  retryable?: boolean;
  onSectionExpand: (section: 'originalText') => void;
  userLanguage?: string; // User's language: 'en', 'zh', 'de', etc.
}

const IqBibleSections: React.FC<IqBibleSectionsProps> = ({
  data,
  loading,
  error,
  retryable,
  userLanguage = 'en',
  onSectionExpand,
}) => {
  const renderOriginalText = () => {
    if (!data.originalText || !Array.isArray(data.originalText) || data.originalText.length === 0) {
      return null;
    }

    const words = data.originalText;

    return (
      <Box>
        <Box sx={{ mb: 2 }}>
          <Typography variant="subtitle2" sx={{ fontWeight: 600, mb: 1 }}>
            {interfaceText('Hebrew Text:')}
          </Typography>
          <Typography
            variant="body1"
            sx={{
              fontFamily: 'serif',
              direction: 'rtl',
              textAlign: 'right',
              fontSize: '1.2rem',
              lineHeight: 1.8,
            }}
          >
            {words.map((word) => word.word).join(' ')}
          </Typography>
        </Box>

        <Box sx={{ mb: 2 }}>
          <Typography variant="subtitle2" sx={{ fontWeight: 600, mb: 1 }}>
            {interfaceText('Word-by-Word Analysis:')}
          </Typography>
          {words.map((word, index) => {
            let pronunciation: any = null;
            try {
              if (word.pronun) {
                pronunciation = JSON.parse(word.pronun);
              }
            } catch (e) {
              // Ignore JSON parse errors
            }

            return (
              <Box
                key={word.id || index}
                sx={{
                  mb: 2,
                  pb: 2,
                  borderBottom: (theme) =>
                    `1px solid ${theme.palette.mode === 'dark' ? 'rgba(255, 255, 255, 0.1)' : 'rgba(0, 0, 0, 0.1)'}`,
                }}
              >
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.5 }}>
                  <Typography
                    variant="body1"
                    sx={{ fontFamily: 'serif', direction: 'rtl', fontSize: '1.1rem' }}
                  >
                    {word.word}
                  </Typography>
                  {word.strongs && (
                    <Typography
                      variant="body2"
                      sx={{ color: 'text.secondary', fontStyle: 'italic' }}
                    >
                      (Strong's {word.strongs})
                    </Typography>
                  )}
                </Box>

                {pronunciation && (
                  <Box sx={{ mb: 0.5 }}>
                    {pronunciation.dic && (
                      <Typography variant="body2" sx={{ color: 'text.secondary' }}>
                        Pronunciation: {pronunciation.dic}
                      </Typography>
                    )}
                  </Box>
                )}

                {word.glossary && (
                  <Typography variant="body2" sx={{ mt: 0.5, whiteSpace: 'pre-wrap' }}>
                    {word.glossary}
                  </Typography>
                )}
              </Box>
            );
          })}
        </Box>
      </Box>
    );
  };

  const renderSection = (
    title: string,
    sectionKey: 'originalText',
    content: React.ReactNode,
    isLoading: boolean,
  ) => {
    return (
      <Accordion
        onChange={(event, expanded) => {
          if (expanded && !data[sectionKey] && !isLoading) {
            onSectionExpand(sectionKey);
          }
        }}
        sx={{
          '&:before': {
            display: 'none',
          },
          boxShadow: 'none',
          borderBottom: (theme) =>
            `1px solid ${theme.palette.mode === 'dark' ? 'rgba(255, 255, 255, 0.1)' : 'rgba(0, 0, 0, 0.1)'}`,
        }}
      >
        <AccordionSummary expandIcon={<ExpandMoreIcon />}>
          <Typography variant="body1" sx={{ fontWeight: 600 }}>
            {title}
          </Typography>
        </AccordionSummary>
        <AccordionDetails>
          {isLoading ? (
            <Box sx={{ display: 'flex', justifyContent: 'center', py: 2 }}>
              <CircularProgress size={20} />
            </Box>
          ) : (
            <Box
              sx={{
                wordWrap: 'break-word',
                overflowWrap: 'break-word',
                whiteSpace: 'normal',
                width: '100%',
                boxSizing: 'border-box',
              }}
            >
              {error ? (
                <Box role={retryable ? 'alert' : 'status'}>
                  <Typography variant="body2">{error}</Typography>
                  {retryable && (
                    <Button onClick={() => onSectionExpand(sectionKey)}>
                      {hebrewResourceMessage(userLanguage, 'retry')}
                    </Button>
                  )}
                </Box>
              ) : (
                content || (
                  <Typography variant="body2" sx={{ fontStyle: 'italic', color: 'text.secondary' }}>
                    {interfaceText('No data available')}
                  </Typography>
                )
              )}
            </Box>
          )}
        </AccordionDetails>
      </Accordion>
    );
  };

  return (
    <Box>
      {renderSection('Original Text', 'originalText', renderOriginalText(), loading.originalText)}
    </Box>
  );
};

export default IqBibleSections;
