import {
  detectReaderLanguages,
  languageEditions,
  normalizeReaderAlias,
  normalizeReaderDigits,
  readerLanguages,
} from '../data/readerLanguages';
import {
  BIBLE_EDITIONS,
  BibleEdition,
  canonicalBook,
  editionChapterCount,
} from '../data/bibleEditions';
import { BibleVerse, loadBibleChapter } from '../services/bibleContent';
import { getTranslationReferencesFromKjv, resolveCanonicalPassage } from './verseMappings';
import { sourceVerseLabelsOverlap } from './sourceVerseLabels';

export type ParsedReaderInput =
  | { kind: 'text'; input: string; text: string }
  | { kind: 'reference'; input: string; reference: string }
  | { kind: 'invalid'; input: string; reason: 'quotes' | 'empty' };

export function parseReaderInput(input: string): ParsedReaderInput {
  const trimmed = input.trim();
  if (!trimmed) {
    return { kind: 'invalid', input, reason: 'empty' };
  }
  const quoted = trimmed.match(/^"([^"\r\n]+)"$/);
  if (quoted?.[1].trim()) {
    return { kind: 'text', input, text: quoted[1].trim() };
  }
  if (trimmed.includes('"')) {
    return { kind: 'invalid', input, reason: 'quotes' };
  }
  return { kind: 'reference', input, reference: normalizeReaderDigits(trimmed) };
}

export interface ReaderContext {
  edition: string;
  /** A language chosen in an actual ambiguity prompt, never inferred from availability. */
  explicitLanguage?: string;
  explicitBook?: string;
}

export interface ReaderPassage {
  book: string;
  chapter: number;
  verse?: string;
  endChapter?: number;
  endVerse?: string;
}

export interface IntentCandidate {
  language: string;
  passage?: ReaderPassage;
  evidence: string;
}

export type ReaderIntentResolution =
  | {
      status: 'resolved';
      input: ParsedReaderInput;
      language: string;
      edition: BibleEdition['id'];
      passage?: ReaderPassage;
      evidence: string;
    }
  | { status: 'ambiguous'; input: ParsedReaderInput; candidates: IntentCandidate[] }
  | {
      status: 'unavailable';
      input: ParsedReaderInput;
      language?: string;
      dependency: 'language-evidence' | 'bible' | 'reference';
      candidates?: IntentCandidate[];
    }
  | { status: 'invalid'; input: ParsedReaderInput; reason: 'quotes' | 'empty' | 'reference' };

export type ResolvedReaderIntent = Extract<ReaderIntentResolution, { status: 'resolved' }>;
export interface ReaderRequest {
  sequence: number;
  intent: ResolvedReaderIntent;
  /** Already validated search hit: retain selection without fetching it again. */
  selectedResult?: {
    id: string;
    book: string;
    chapter: number;
    verse: string | number;
    text: string;
    translation: string;
  };
}
export type ApplyReaderIntent = (
  intent: ResolvedReaderIntent,
  selectedResult?: ReaderRequest['selectedResult'],
) => void;
export class ReaderIntentError extends Error {
  constructor(public readonly resolution: Exclude<ReaderIntentResolution, ResolvedReaderIntent>) {
    super(resolution.status);
    this.name = 'ReaderIntentError';
  }
}

/** Navigation already identifies its source edition; do not redetect language from canonical keys. */
export function passageReaderIntent(
  editionId: string,
  passage: ReaderPassage,
): ResolvedReaderIntent {
  const edition = BIBLE_EDITIONS.find((entry) => entry.id === editionId);
  const book = canonicalBook(passage.book);
  if (
    !edition ||
    !book ||
    !Number.isSafeInteger(passage.chapter) ||
    passage.chapter < 1 ||
    passage.chapter > editionChapterCount(book, edition.id)
  ) {
    throw new Error('This requested Bible passage is unavailable.');
  }
  const input = `${book} ${passage.chapter}${passage.verse !== undefined ? `:${passage.verse}` : ''}${passage.endVerse !== undefined ? `-${passage.endChapter !== undefined && passage.endChapter !== passage.chapter ? `${passage.endChapter}:` : ''}${passage.endVerse}` : ''}`;
  return {
    status: 'resolved',
    input: { kind: 'reference', input, reference: input },
    language: edition.locale,
    edition: edition.id,
    passage: { ...passage, book },
    evidence: 'navigation',
  };
}

/** Explicit edition changes preserve the content currently being read or the current text query. */
export function readerIntentForEdition(
  editionId: string,
  sourceEdition: string,
  rows: readonly BibleVerse[],
  previous?: ResolvedReaderIntent,
): ResolvedReaderIntent {
  const edition = BIBLE_EDITIONS.find((entry) => entry.id === editionId);
  if (!edition) {
    throw new Error('This Bible edition is unavailable.');
  }
  if (!rows.length && previous?.input.kind === 'text') {
    return {
      ...previous,
      language: edition.locale,
      edition: edition.id,
      evidence: 'explicit-edition',
    };
  }
  const first = rows[0];
  const last = rows[rows.length - 1];
  if (!first || !last) {
    throw new Error('Load the source passage before resolving its full content.');
  }
  const start = resolveCanonicalPassage({
    translation: sourceEdition,
    book: first.book.trim(),
    chapter: Number(first.chapter),
    verse: first.verse,
  });
  const end = resolveCanonicalPassage({
    translation: sourceEdition,
    book: last.book.trim(),
    chapter: Number(last.chapter),
    verse: last.verse,
  });
  const targets = getTranslationReferencesFromKjv(edition.id, start.kjvSpan[0]);
  const ends = getTranslationReferencesFromKjv(edition.id, end.kjvSpan[end.kjvSpan.length - 1]);
  const target = targets[0];
  const ending = ends[ends.length - 1];
  if (!target || !ending || target.book !== ending.book) {
    throw new Error('This passage needs verified correspondence before changing its edition.');
  }
  const passage: ReaderPassage = {
    book: target.book,
    chapter: target.chapter,
    verse: String(target.verse),
    endChapter: ending.chapter,
    endVerse: String(ending.verse),
  };
  return {
    ...passageReaderIntent(edition.id, passage),
    evidence: 'explicit-edition',
  };
}

/** Preserve actual source order, including zero and combined stored labels. */
export function selectReaderPassageRows(
  rows: readonly BibleVerse[],
  passage: ReaderPassage,
): BibleVerse[] {
  const endChapter = passage.endChapter ?? passage.chapter;
  const start =
    passage.verse === undefined
      ? 0
      : rows.findIndex(
          (row) =>
            Number(row.chapter) === passage.chapter &&
            sourceVerseLabelsOverlap(row.verse, passage.verse),
        );
  const endLabel = passage.endVerse ?? passage.verse;
  const end =
    endLabel === undefined
      ? rows.length - 1
      : rows.reduce(
          (last, row, index) =>
            Number(row.chapter) === endChapter && sourceVerseLabelsOverlap(row.verse, endLabel)
              ? index
              : last,
          -1,
        );
  if (start < 0 || end < start) {
    throw new Error('The requested source reference is not available.');
  }
  return rows.slice(start, end + 1);
}

/** An edition switch during a pending load resolves the requested full passage first. */
export async function resolveReaderEditionChange(
  editionId: string,
  sourceEdition: string,
  rows: readonly BibleVerse[],
  previous?: ResolvedReaderIntent,
  signal?: AbortSignal,
): Promise<ResolvedReaderIntent> {
  if (rows.length || previous?.input.kind === 'text') {
    return readerIntentForEdition(editionId, sourceEdition, rows, previous);
  }
  const passage = previous?.passage || { book: 'genesis', chapter: 1 };
  const source: BibleVerse[] = [];
  for (
    let chapter = passage.chapter;
    chapter <= (passage.endChapter ?? passage.chapter);
    chapter++
  ) {
    source.push(...(await loadBibleChapter(sourceEdition, passage.book, chapter, signal)));
  }
  if (signal?.aborted) {
    throw new DOMException('Cancelled', 'AbortError');
  }
  return readerIntentForEdition(
    editionId,
    sourceEdition,
    selectReaderPassageRows(source, passage),
    previous,
  );
}

function referenceCandidates(reference: string): IntentCandidate[] {
  const normalized = normalizeReaderAlias(reference).replace(/[–—]/g, '-');
  const matches: (IntentCandidate & { aliasLength: number })[] = [];
  for (const [language, profile] of Object.entries(readerLanguages)) {
    for (const [alias, meanings] of Object.entries(profile.aliases)) {
      const key = normalizeReaderAlias(normalizeReaderDigits(alias));
      if (!normalized.startsWith(key)) {
        continue;
      }
      const suffix = normalized.slice(key.length);
      const parsed = suffix.match(/^(?:([1-9]\d*)(?::(\d*)(?:-(?:([1-9]\d*):)?(\d+))?)?)?$/);
      if (!parsed) {
        continue;
      }
      const chapter = Number(parsed[1] || 1);
      const verse = parsed[2] || undefined;
      const endChapter = parsed[4] ? Number(parsed[3] || chapter) : undefined;
      if (
        !Number.isSafeInteger(chapter) ||
        (verse !== undefined && !Number.isSafeInteger(Number(verse))) ||
        (endChapter !== undefined &&
          (!Number.isSafeInteger(endChapter) ||
            endChapter < chapter ||
            !Number.isSafeInteger(Number(parsed[4])) ||
            (endChapter === chapter && Number(parsed[4]) < Number(verse))))
      ) {
        continue;
      }
      for (const meaning of meanings) {
        matches.push({
          language,
          passage: {
            book: meaning.book,
            chapter,
            ...(verse !== undefined ? { verse } : {}),
            ...(endChapter !== undefined ? { endChapter, endVerse: parsed[4] } : {}),
          },
          evidence: meaning.evidence,
          aliasLength: key.length,
        });
      }
    }
  }
  const longest = Math.max(0, ...matches.map((match) => match.aliasLength));
  const unique = new Map<string, IntentCandidate>();
  for (const { aliasLength, ...match } of matches) {
    if (aliasLength === longest) {
      unique.set(`${match.language}:${JSON.stringify(match.passage)}`, match);
    }
  }
  return [...unique.values()];
}

export function resolveReaderIntent(
  input: ParsedReaderInput,
  context: ReaderContext,
): ReaderIntentResolution {
  if (input.kind === 'invalid') {
    return { status: 'invalid', input, reason: input.reason };
  }
  const active = BIBLE_EDITIONS.find((edition) => edition.id === context.edition);
  let candidates: IntentCandidate[] =
    input.kind === 'reference'
      ? referenceCandidates(input.reference)
      : detectReaderLanguages(input.text).map(({ locale, reason }) => ({
          language: locale,
          evidence: reason,
        }));
  if (
    input.kind === 'text' &&
    context.explicitLanguage &&
    readerLanguages[context.explicitLanguage]
  ) {
    candidates = [{ language: context.explicitLanguage, evidence: 'explicit-language' }];
  }
  if (input.kind === 'reference' && candidates.length > 1 && !context.explicitLanguage) {
    // Imported English fallback labels and old permissive aliases do not establish
    // foreign-language intent. Prefer positive corpus evidence over those labels.
    const evidence = detectReaderLanguages(input.reference.replace(/[\p{N}:–—-]/gu, ' '));
    if (evidence.length === 1 && evidence[0].reason !== 'corpus') {
      const evidenced = candidates.filter((candidate) => candidate.language === evidence[0].locale);
      if (evidenced.length) {
        candidates = evidenced;
      }
    }
  }
  if (!candidates.length) {
    if (input.kind === 'reference') {
      const reference = normalizeReaderAlias(input.reference);
      const sourceLanguages = Object.entries(readerLanguages).filter(([, profile]) =>
        profile.unresolvedSourceAliases.some((path) => {
          const alias = normalizeReaderAlias(
            normalizeReaderDigits(path.slice(path.lastIndexOf('/') + 1)),
          );
          return (
            reference.startsWith(alias) &&
            /^(?:\d+(?::\d*(?:-\d+)?)?)?$/.test(reference.slice(alias.length))
          );
        }),
      );
      if (!sourceLanguages.length) {
        return { status: 'invalid', input, reason: 'quotes' };
      }
      const preferred = sourceLanguages.filter(
        ([locale]) => locale === (context.explicitLanguage || active?.locale),
      );
      const possible = preferred.length ? preferred : sourceLanguages;
      if (possible.length > 1) {
        return {
          status: 'ambiguous',
          input,
          candidates: possible.map(([language]) => ({ language, evidence: 'source-book-alias' })),
        };
      }
      return {
        status: 'unavailable',
        input,
        dependency: languageEditions(possible[0][0]).length ? 'reference' : 'bible',
        language: possible[0][0],
      };
    }
    return {
      status: 'unavailable',
      input,
      dependency: 'language-evidence',
    };
  }
  // An explicit choice is authoritative; ambient current edition resolves only genuine ties.
  const contextual = candidates.filter(
    (candidate) => candidate.language === (context.explicitLanguage || active?.locale),
  );
  if (context.explicitLanguage && !contextual.length) {
    return {
      status: 'unavailable',
      input,
      language: context.explicitLanguage,
      dependency: 'language-evidence',
    };
  }
  if (contextual.length) {
    candidates = contextual;
  }
  if (context.explicitBook) {
    candidates = candidates.filter((candidate) => candidate.passage?.book === context.explicitBook);
    if (!candidates.length) {
      return { status: 'invalid', input, reason: 'reference' };
    }
  }
  if (candidates.length !== 1) {
    return { status: 'ambiguous', input, candidates };
  }
  const candidate = candidates[0];
  const editions = languageEditions(candidate.language);
  const edition = editions.find((entry) => entry.id === active?.id) || editions[0];
  if (!edition) {
    return {
      status: 'unavailable',
      input,
      language: candidate.language,
      dependency: 'bible',
      candidates,
    };
  }
  if (
    candidate.passage &&
    (candidate.passage.chapter > editionChapterCount(candidate.passage.book, edition.id) ||
      (candidate.passage.endChapter || candidate.passage.chapter) >
        editionChapterCount(candidate.passage.book, edition.id))
  ) {
    return { status: 'invalid', input, reason: 'reference' };
  }
  return {
    status: 'resolved',
    input,
    language: candidate.language,
    edition: edition.id,
    passage: candidate.passage,
    evidence: candidate.evidence,
  };
}
