import { interfaceText } from '../../i18n/interfaceText';
import { devError } from '../../utils/developmentDiagnostics';
import React, { useState } from 'react';
import {
  Box,
  Typography,
  Button,
  Chip,
  Paper,
  CircularProgress,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogContentText,
  DialogActions,
} from '@mui/material';
import { Link as RouterLink } from 'react-router-dom';
import { useSubscription } from '../../contexts/SubscriptionContext';
import { cancelSubscription } from '../../services/stripe';

/**
 * Component to display subscription status and management options.
 */
const SubscriptionStatus: React.FC = () => {
  const { subscription, refreshStatus } = useSubscription();
  const [loading, setLoading] = useState(false);
  const [openDialog, setOpenDialog] = useState(false);

  const handleCancelSubscription = async () => {
    if (!subscription.subscriptionId) {
      return;
    }

    setLoading(true);
    try {
      await cancelSubscription(subscription.subscriptionId);
      await refreshStatus();
      setOpenDialog(false);
    } catch (error) {
      devError('Error cancelling subscription.');
    } finally {
      setLoading(false);
    }
  };

  const formatDate = (dateString: string | null) => {
    if (!dateString) {
      return 'Unknown';
    }
    return new Date(dateString).toLocaleDateString();
  };

  return (
    <Paper
      elevation={3}
      sx={{
        padding: 3,
        border: '1px solid',
        borderColor: 'divider',
        borderRadius: 2,
        marginBottom: 3,
        backgroundColor: (theme) => (theme.palette.mode === 'dark' ? '#212121' : '#FFFFFF'),
      }}
    >
      <Box sx={{ display: 'flex', justifyContent: 'flex-end', alignItems: 'center', mb: 2 }}>
        <Typography variant="h6" sx={{ mr: 2 }}>
          {interfaceText('Subscription Status')}
        </Typography>
        {subscription.isActive && (
          <Chip label={interfaceText('Active')} color="success" size="small" variant="outlined" />
        )}
        {!subscription.isActive && (
          <Chip label={interfaceText('Inactive')} color="error" size="small" variant="outlined" />
        )}
      </Box>

      {subscription.isActive ? (
        <>
          <Box sx={{ mb: 2, textAlign: 'right' }}>
            <Typography variant="body2" color="text.secondary" gutterBottom>
              {interfaceText('Plan:')}
            </Typography>
            <Typography variant="body1">
              {subscription.plan === 'yearly'
                ? interfaceText('Yearly Premium')
                : interfaceText('Monthly Premium')}
            </Typography>
          </Box>

          {/* Check if subscription is in trial period */}
          {subscription.expiresAt && (
            <Box sx={{ mb: 2, textAlign: 'right' }}>
              <Typography variant="body2" color="text.secondary" gutterBottom>
                {subscription.status === 'trialing'
                  ? interfaceText('Free Trial Until:')
                  : interfaceText('Renewal Date:')}
              </Typography>
              <Typography variant="body1">{formatDate(subscription.expiresAt)}</Typography>
              {subscription.status === 'trialing' && (
                <Typography variant="body2" color="primary" sx={{ mt: 1, fontStyle: 'italic' }}>
                  You're currently in your free trial period. Your first payment will be processed
                  on {formatDate(subscription.expiresAt)}.
                </Typography>
              )}
            </Box>
          )}

          <Box sx={{ mt: 3, textAlign: 'left' }}>
            <Button variant="outlined" color="error" onClick={() => setOpenDialog(true)}>
              {interfaceText('Cancel Subscription')}
            </Button>
          </Box>

          {/* Cancel Confirmation Dialog */}
          <Dialog open={openDialog} onClose={() => setOpenDialog(false)}>
            <DialogTitle>{interfaceText('Cancel Subscription?')}</DialogTitle>
            <DialogContent>
              <DialogContentText>
                {interfaceText(
                  'Are you sure you want to cancel your subscription? You will lose access to premium features at the end of your current billing period.',
                )}
              </DialogContentText>
            </DialogContent>
            <DialogActions>
              <Button sx={{ color: '#A1A1A1' }} onClick={() => setOpenDialog(false)}>
                {interfaceText('Keep Subscription')}
              </Button>
              <Button onClick={handleCancelSubscription} color="error" disabled={loading}>
                {loading ? <CircularProgress size={24} /> : interfaceText('Yes, Cancel')}
              </Button>
            </DialogActions>
          </Dialog>
        </>
      ) : (
        <Box>
          <Typography variant="body2" color="text.secondary" paragraph>
            {interfaceText("You don't currently have an active subscription.")}
          </Typography>
          <Button variant="contained" color="primary" component={RouterLink} to="/subscribe">
            {interfaceText('Subscribe Now')}
          </Button>
        </Box>
      )}
    </Paper>
  );
};

export default SubscriptionStatus;
